import{_ as e,c as a,o as i,ae as o}from"./chunks/framework.BGWP4WZ_.js";const n="/py-xiaozhi/assets/System_interface.u2hgB9Pj.png",m=JSON.parse('{"title":"Voice Interaction Mode Description","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03_Voice_Interaction_Mode_Guide.md","filePath":"guide/03_Voice_Interaction_Mode_Guide.md"}'),s={name:"guide/03_Voice_Interaction_Mode_Guide.md"};function r(l,t,c,d,h,u){return i(),a("div",null,t[0]||(t[0]=[o('<h1 id="voice-interaction-mode-description" tabindex="-1">Voice Interaction Mode Description <a class="header-anchor" href="#voice-interaction-mode-description" aria-label="Permalink to &quot;Voice Interaction Mode Description&quot;">​</a></h1><p><img src="'+n+`" alt="Image"></p><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p>py-xiaozhi is an intelligent voice interaction assistant that supports various operation modes and features, including voice conversation, IoT device control, visual recognition, and more. This document primarily introduces the basic usage of voice interaction.</p><h2 id="voice-interaction-modes" tabindex="-1">Voice Interaction Modes <a class="header-anchor" href="#voice-interaction-modes" aria-label="Permalink to &quot;Voice Interaction Modes&quot;">​</a></h2><p>Voice interaction supports two modes. You can choose the appropriate mode based on your needs:</p><h3 id="_1-press-and-hold-conversation-mode" tabindex="-1">1. Press-and-Hold Conversation Mode <a class="header-anchor" href="#_1-press-and-hold-conversation-mode" aria-label="Permalink to &quot;1. Press-and-Hold Conversation Mode&quot;">​</a></h3><ul><li><strong>How to Use</strong>: Press and hold the talk button, release to send</li><li><strong>Suitable Scenarios</strong>: Short exchanges, precise control of conversation start and end times</li><li><strong>Advantages</strong>: Avoids accidental triggers, precise control</li><li><strong>Shortcut Key</strong>: Alt+Shift+V (Press and hold to talk)</li></ul><h3 id="_2-automatic-conversation-mode" tabindex="-1">2. Automatic Conversation Mode <a class="header-anchor" href="#_2-automatic-conversation-mode" aria-label="Permalink to &quot;2. Automatic Conversation Mode&quot;">​</a></h3><ul><li><strong>How to Use</strong>: Click to start the conversation, the system automatically detects and sends voice</li><li><strong>Suitable Scenarios</strong>: Long exchanges, no manual control required</li><li><strong>Advantages</strong>: Hands-free, natural communication</li><li><strong>Interface Prompt</strong>: Displays &quot;Listening&quot; to indicate the system is receiving your voice</li><li><strong>Shortcut Key</strong>: Alt+Shift+A (Start automatic conversation)</li></ul><h3 id="mode-switching" tabindex="-1">Mode Switching <a class="header-anchor" href="#mode-switching" aria-label="Permalink to &quot;Mode Switching&quot;">​</a></h3><ul><li>The current mode is displayed in the bottom-right corner of the GUI</li><li>Click the button to switch modes</li><li>Use the Alt+Shift+M shortcut key to switch modes</li><li>The default mode can be set via the configuration file</li></ul><h2 id="conversation-control" tabindex="-1">Conversation Control <a class="header-anchor" href="#conversation-control" aria-label="Permalink to &quot;Conversation Control&quot;">​</a></h2><h3 id="interrupt-function" tabindex="-1">Interrupt Function <a class="header-anchor" href="#interrupt-function" aria-label="Permalink to &quot;Interrupt Function&quot;">​</a></h3><p>When the system is replying with voice, you can interrupt at any time:</p><ul><li><strong>GUI Mode</strong>: Use Alt+Shift+X or the interrupt button on the interface</li><li><strong>CLI Mode</strong>: Use the F3 key</li></ul><h2 id="system-tray" tabindex="-1">System Tray <a class="header-anchor" href="#system-tray" aria-label="Permalink to &quot;System Tray&quot;">​</a></h2><p>The GUI mode supports system tray functionality:</p><ul><li><strong>Status Indicator</strong>: The tray icon color reflects the current system status <ul><li>Green: Started/Idle</li><li>Yellow: Listening</li><li>Blue: Speaking</li><li>Red: Error</li><li>Gray: Disconnected</li></ul></li><li><strong>Minimize</strong>: Automatically minimizes to the system tray when the window is closed</li><li><strong>Exit</strong>: Right-click the tray icon and select &quot;Exit Program&quot; to fully exit the application</li></ul><h3 id="state-transitions" tabindex="-1">State Transitions <a class="header-anchor" href="#state-transitions" aria-label="Permalink to &quot;State Transitions&quot;">​</a></h3><p>The voice interaction system has the following states:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        +----------------+</span></span>
<span class="line"><span>                        |                |</span></span>
<span class="line"><span>                        v                |</span></span>
<span class="line"><span>+------+  Wake Word/   +------------+   |   +------------+</span></span>
<span class="line"><span>| IDLE |   Button     | CONNECTING | --+-&gt; | LISTENING  |</span></span>
<span class="line"><span>+------+ ------------&gt; +------------+       +------------+</span></span>
<span class="line"><span>   ^                                            |</span></span>
<span class="line"><span>   |                                            | Voice recognition complete</span></span>
<span class="line"><span>   |          +------------+                    v</span></span>
<span class="line"><span>   +--------- |  SPEAKING  | &lt;-----------------+</span></span>
<span class="line"><span>     Playback +------------+</span></span></code></pre></div><ul><li><strong>IDLE</strong>: Idle state, waiting for a wake word or button trigger</li><li><strong>CONNECTING</strong>: Connecting to the server</li><li><strong>LISTENING</strong>: Listening to user voice</li><li><strong>SPEAKING</strong>: System is replying with voice</li></ul><h2 id="shortcut-key-summary" tabindex="-1">Shortcut Key Summary <a class="header-anchor" href="#shortcut-key-summary" aria-label="Permalink to &quot;Shortcut Key Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Shortcut Key</th><th>Description</th></tr></thead><tbody><tr><td>Press to Talk</td><td>Alt+Shift+V</td><td>Press and hold to record, release to send (manual mode only)</td></tr><tr><td>Auto Talk</td><td>Alt+Shift+A</td><td>Start automatic conversation (auto-detect and send voice)</td></tr><tr><td>Interrupt</td><td>Alt+Shift+X</td><td>Interrupt the current AI reply</td></tr><tr><td>Switch Mode</td><td>Alt+Shift+M</td><td>Switch between manual and automatic modes</td></tr></tbody></table><h2 id="voice-commands" tabindex="-1">Voice Commands <a class="header-anchor" href="#voice-commands" aria-label="Permalink to &quot;Voice Commands&quot;">​</a></h2><p>The system supports various voice commands. Below are common examples:</p><h3 id="basic-interaction" tabindex="-1">Basic Interaction <a class="header-anchor" href="#basic-interaction" aria-label="Permalink to &quot;Basic Interaction&quot;">​</a></h3><ul><li>&quot;Hello&quot;/&quot;Who are you&quot; - Basic greetings and identity inquiries</li><li>&quot;Thank you&quot;/&quot;Goodbye&quot; - Polite expressions</li></ul><h3 id="iot-control" tabindex="-1">IoT Control <a class="header-anchor" href="#iot-control" aria-label="Permalink to &quot;IoT Control&quot;">​</a></h3><ul><li>&quot;Turn on/off the living room light&quot; - Control lighting</li><li>&quot;Play Chrysanthemum Terrace on the IoT music player&quot; - Start playing music</li></ul><h3 id="visual-recognition" tabindex="-1">Visual Recognition <a class="header-anchor" href="#visual-recognition" aria-label="Permalink to &quot;Visual Recognition&quot;">​</a></h3><ul><li>&quot;Open the camera&quot; - Turn on the camera</li><li>&quot;Analyze the scene&quot; - Analyze the current scene</li><li>&quot;What do you see&quot; - AI describes the recognized content</li><li>&quot;Close the camera&quot; - Turn off the camera</li></ul><h2 id="run-modes" tabindex="-1">Run Modes <a class="header-anchor" href="#run-modes" aria-label="Permalink to &quot;Run Modes&quot;">​</a></h2><h3 id="gui-mode-default" tabindex="-1">GUI Mode (Default) <a class="header-anchor" href="#gui-mode-default" aria-label="Permalink to &quot;GUI Mode (Default)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span></span></code></pre></div><h3 id="cli-mode" tabindex="-1">CLI Mode <a class="header-anchor" href="#cli-mode" aria-label="Permalink to &quot;CLI Mode&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span></span></code></pre></div><h3 id="build-and-package" tabindex="-1">Build and Package <a class="header-anchor" href="#build-and-package" aria-label="Permalink to &quot;Build and Package&quot;">​</a></h3><p>Use PyInstaller to package into an executable file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Universal command for all platforms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.py</span></span></code></pre></div><h2 id="platform-compatibility" tabindex="-1">Platform Compatibility <a class="header-anchor" href="#platform-compatibility" aria-label="Permalink to &quot;Platform Compatibility&quot;">​</a></h2><ul><li><strong>Windows</strong>: Fully supports all features</li><li><strong>macOS</strong>: <ul><li>System tray appears in the top status bar instead of the taskbar</li><li>Shortcut keys may require system permission authorization</li></ul></li><li><strong>Linux</strong>: <ul><li>System tray support may vary depending on the desktop environment (GNOME/KDE/Xfce, etc.)</li><li>Some distributions may require additional system tray support packages</li></ul></li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Clear Pronunciation</strong>: Ensure clear pronunciation in a quiet environment</li><li><strong>Pause Appropriately</strong>: Pausing between sentences helps with system recognition</li><li><strong>Use Wake Words</strong>: Enable wake word functionality to avoid accidental triggers</li><li><strong>Check Feedback</strong>: Pay attention to interface status prompts to understand the system&#39;s current state</li><li><strong>Concise Commands</strong>: Use concise and clear commands for better recognition results</li></ol><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you encounter issues:</p><ol><li>First, check the <code>docs/error_summary.md</code> document</li><li>Submit an issue via GitHub Issues</li><li>Seek help from the AI assistant</li><li>Contact the author (WeChat available on the homepage). Please prepare a Todesk link and explain your purpose. The author handles requests on weekday evenings.</li></ol>`,48)]))}const g=e(s,[["render",r]]);export{m as __pageData,g as default};
